import {GitHub} from './github.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escape=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api=null,posts={posts:[]},photos={photos:[]},imports={imports:[]},overrides={articles:{}},settings={},sync={sources:{}},archived=[],busy=false,dirty=false;
function notice(text,error=false){$('#notice').textContent=text;$('#notice').className=error?'error':'';$('#notice').hidden=false}
async function task(fn){if(busy)return;busy=true;$$('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){notice(e.message,true)}finally{busy=false;$$('button').forEach(b=>b.disabled=false)}}
function tab(name){$$('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==name);$$('[data-tab]').forEach(b=>{if(b.dataset.tab===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function today(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function image(file){if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))throw Error(file.name+': choose a JPEG, PNG, WebP or AVIF image.');if(file.size>20*1024*1024)throw Error(file.name+': image must be below 20 MB.');let source,release=()=>{};try{source=await createImageBitmap(file);release=()=>source.close()}catch(fastError){const url=URL.createObjectURL(file),photo=new Image();release=()=>URL.revokeObjectURL(url);try{await new Promise((resolve,reject)=>{photo.onload=resolve;photo.onerror=()=>reject(Error('decode failed'));photo.src=url});source=photo}catch(error){release();throw Error(file.name+': the image could not be decoded. Open it in your gallery, save a fresh JPEG copy, then select that copy.')}}const width=source.naturalWidth||source.width,height=source.naturalHeight||source.height;if(width*height>80_000_000){release();throw Error(file.name+': image dimensions are too large. Resize before uploading.')}const scale=Math.min(1,1800/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);try{canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height)}catch(error){release();throw Error(file.name+': this image could not be prepared. Save a fresh JPEG copy and try again.')}release();const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.86));if(!blob||blob.type!=='image/webp')throw Error('This browser cannot encode WebP. Update the browser and try again.');return new Uint8Array(await blob.arrayBuffer())}
async function load(){try{await api.snapshot();[posts,photos,imports,overrides,settings,sync]=await Promise.all([api.read('content/posts.json',{posts:[]}),api.read('content/photos.json',{photos:[]}),api.read('content/imports.json',{imports:[]}),api.read('content/overrides.json',{articles:{}}),api.read('content/settings.json',{}),api.read('content/sync-state.json',{sources:{}})]);const tree=await api.call('/git/trees/'+api.tree+'?recursive=1');if(tree.truncated)throw Error('Repository tree is too large to list safely. No changes made.');api.files=Object.fromEntries(tree.tree.map(x=>[x.path,x.sha]));archived=tree.tree.filter(x=>/^content\/articles\/[a-f0-9]+\.json$/.test(x.path)).map(x=>({path:x.path,id:x.path.split('/').pop().replace('.json','')}));render();fillSettings()}catch(e){api.head=null;api.tree=null;throw e}}
function render(){renderStories();renderPhotos();renderImports();const sources=Object.entries(sync.sources||{}),pending=sources.filter(([,s])=>!s.last_success&&!['author_unverified','unsupported'].includes(s.status));const unsupported=sources.filter(([,s])=>s.status==='unsupported');$('#sync-status').replaceChildren();for(const [label,value] of [['Last completed check',sync.last_completed||'Not run yet'],['Author listing scan',sync.listing_complete?'Complete':'In progress'],['Known URLs',sources.length],['Saved in last run',sync.saved_this_run||0],['Waiting to be archived',pending.length],['Multimedia pages without article text',unsupported.length],['Local archived records',archived.length]]){const p=document.createElement('p');p.textContent=label+': '+value;$('#sync-status').append(p)}$('#sync-pending-list').replaceChildren();if(pending.length){const h=document.createElement('h3');h.textContent='Waiting articles';$('#sync-pending-list').append(h);for(const [url,state] of pending){const p=document.createElement('p');p.className='manageritem';p.textContent=(state.title||url.split('/').pop().replace(/-/g,' '))+(state.error?' — '+state.error:'');$('#sync-pending-list').append(p)}}$('#sync-errors').textContent=(sync.errors||[]).join('\n')||'No warnings recorded.'}
function renderStories(){const term=$('#manager-search').value.toLowerCase();const manual=posts.posts.filter(a=>a.title.toLowerCase().includes(term));$('#story-manager').innerHTML=manual.map(a=>`<article class="manageritem"><small>${escape(a.status)} · ${escape(a.stream)} · ${escape(a.date_published?.slice(0,10))}</small><h3>${escape(a.title)}</h3><button data-edit="${escape(a.id)}">Edit story</button></article>`).join('');const head=document.createElement('h3');head.textContent='Imported and archived stories';$('#story-manager').append(head);const links=Object.entries(sync.sources||{}).filter(([u,s])=>s.article_id&&(s.title||u).toLowerCase().includes(term));for(const [u,s] of links){const a=document.createElement('article');a.className='manageritem';const title=document.createElement('p');title.textContent=s.title||u.split('/').pop().replace(/-/g,' ');const b=document.createElement('button');b.textContent='Edit classification';b.onclick=()=>task(()=>review(s.article_id,a));a.append(title,b);$('#story-manager').append(a)}if(!manual.length&&!links.length){const p=document.createElement('p');p.textContent='No matching stories. Reload after the next import run.';$('#story-manager').append(p)}$$('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit))}
function edit(id){const a=posts.posts.find(x=>x.id===id);if(!a)return;if(dirty&&!confirm('Replace unsaved editor text? Download it first if needed.'))return;$('#story-id').value=id;$('#story-title').value=a.title;$('#story-stream').value=a.stream||'thoughts';$('#story-category').value=a.category||'';$('#story-date').value=a.date_published?.slice(0,10)||today();$('#story-excerpt').value=a.excerpt||'';$('#story-format').value=a.format||(a.body_html?'html':'text');$('#story-body').value=a.body||a.body_html||'';$('#story-alt').value=a.cover_alt||'';$('#story-credit').value=a.cover_credit||'';$('#story-cover').value='';$('#story-source-url').value=a.source_url||'';$('#story-source-name').value=a.source_name||'';$('#story-original-byline').value=(a.original_authors||[]).join(', ');$('#story-contribution').value=a.contribution||'';$('#story-republish-rights').checked=!!a.rights_confirmed;$('#editor-title').textContent='Edit story';dirty=false;tab('write');window.scrollTo({top:0,behavior:'smooth'})}
function draft(){return{source_url:$('#story-source-url').value.trim(),source_name:$('#story-source-name').value.trim(),original_authors:$('#story-original-byline').value.split(',').map(v=>v.trim()).filter(Boolean),contribution:$('#story-contribution').value.trim(),rights_confirmed:$('#story-republish-rights').checked,title:$('#story-title').value.trim(),stream:$('#story-stream').value,category:$('#story-category').value.trim(),date_published:$('#story-date').value+'T00:00:00+06:00',excerpt:$('#story-excerpt').value.trim(),format:$('#story-format').value,body:$('#story-body').value,cover_alt:$('#story-alt').value,cover_credit:$('#story-credit').value}}
async function saveStory(status){if(!$('#story-form').reportValidity())return;const data=draft();if(data.source_url){const u=new URL(data.source_url);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use a public HTTPS source URL.');if(!data.source_name||!data.original_authors.length||!data.contribution||!data.rights_confirmed)throw Error('Add the publication, original byline, your contribution and republication permission.');}if(!data.body.trim())throw Error('Add the story text.');const id=$('#story-id').value||crypto.randomUUID();const old=posts.posts.find(x=>x.id===id)||{},rawSlug=data.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),storySlug=((rawSlug.length>75?rawSlug.slice(0,75).replace(/-[^-]*$/,''):rawSlug)||'story'),base='thoughts/'+storySlug+'/',taken=posts.posts.some(x=>x.id!==id&&x.local_url===base),localUrl=old.local_url||(taken?'thoughts/'+storySlug+'-'+(data.date_published.slice(0,4)||id.slice(0,8))+'/':base);const item={...old,...data,id,status,updated_at:new Date().toISOString(),local_url:localUrl,original_authors:data.source_url?data.original_authors:['Arafat Rahaman'],manual_import:!!data.source_url,verified_author:data.source_url?data.original_authors.includes('Arafat Rahaman'):true,first_archived_at:old.first_archived_at||new Date().toISOString()};const files=[];const file=$('#story-cover').files[0];if(file){notice('Preparing cover photograph…');const path='site/assets/uploads/'+crypto.randomUUID()+'.webp';files.push({path,bytes:await image(file)});item.cover_image=path.replace(/^site\//,'')}const next={posts:posts.posts.some(x=>x.id===id)?posts.posts.map(x=>x.id===id?item:x):[item,...posts.posts]};files.push({path:'content/posts.json',data:next});await api.commit(files,(status==='draft'?'Save draft: ':'Publish: ')+item.title);posts=next;$('#story-id').value=id;dirty=false;renderStories();notice(status==='draft'?'Draft saved to the repository. It is excluded from the public website.':'Story saved. Publication follows the GitHub Pages deployment; check deployment status above.')}
function renderPhotos(){$('#photo-manager').innerHTML=photos.photos.map(p=>`<article><img src="../${escape(p.src)}" alt="${escape(p.alt)}"><p>${escape(p.caption)}</p><small>${escape(p.status||'published')}</small><div class="actions"><button data-edit-photo="${escape(p.id)}">Edit details</button><button data-hide-photo="${escape(p.id)}">${p.status==='hidden'?'Restore':'Hide'}</button></div></article>`).join('');$$('[data-hide-photo]').forEach(b=>b.onclick=()=>task(async()=>{const next={photos:photos.photos.map(p=>p.id===b.dataset.hidePhoto?{...p,status:p.status==='hidden'?'published':'hidden'}:p)};await api.commit([{path:'content/photos.json',data:next}],'Update photograph visibility');photos=next;renderPhotos();notice('Visibility saved. The original image remains recoverable in the repository.')}));$$('[data-edit-photo]').forEach(b=>b.onclick=()=>{const p=photos.photos.find(x=>x.id===b.dataset.editPhoto);const caption=prompt('Caption',p.caption||'');if(caption===null)return;const alt=prompt('Image description',p.alt||'');if(alt===null)return;task(async()=>{const next={photos:photos.photos.map(x=>x.id===p.id?{...x,caption,alt}:x)};await api.commit([{path:'content/photos.json',data:next}],'Edit photograph details');photos=next;renderPhotos();notice('Photograph details saved.')})})}
let photoObjectUrls=[];
function renderPhotoBatch(files){photoObjectUrls.forEach(URL.revokeObjectURL);photoObjectUrls=[];$('#photo-batch').replaceChildren();files.forEach((file,index)=>{const url=URL.createObjectURL(file);photoObjectUrls.push(url);const base=file.name.replace(/\.[^.]+$/,'').replace(/[-_]+/g,' ').trim();const card=document.createElement('article');card.innerHTML=`<img src="${url}" alt=""><strong>${escape(file.name)}</strong><label>Caption<input data-photo-caption="${index}" value="${escape(base)}" required maxlength="300"></label><label>Location<input data-photo-location="${index}" maxlength="150"></label><label>Date<input data-photo-date="${index}" type="date" value="${today()}"></label><label>Image description<input data-photo-alt="${index}" value="Photograph by Arafat Rahaman" required maxlength="300"></label>`;$('#photo-batch').append(card)})}
function renderImports(){$('#import-manager').replaceChildren();for(const item of imports.imports){const state=sync.sources?.[item.url],section=item.stream==='opinion'?'Opinion & Analysis':item.stream==='thoughts'?'Thoughts':'Reports & Features',credit=item.credit_type==='author-page'?'Bylined article':'Non-byline contribution';const a=document.createElement('article');a.className='manageritem';const title=document.createElement('p');title.textContent=item.url;const meta=document.createElement('small');meta.textContent=(state?.status||'queued')+' · '+section+' · '+credit+' · '+(state?.error||item.contribution);a.append(title,meta);if(state?.article_id){const b=document.createElement('button');b.textContent='Edit classification';b.onclick=()=>task(()=>review(state.article_id,a));a.append(document.createElement('br'),b)}$('#import-manager').append(a)}}
async function review(id,host){
 const original=await api.read('content/articles/'+id+'.json',null);if(!original)throw Error('This record is not available yet.');
 const saved=overrides.articles[id]||{},a={...original,...saved},inferredCredit=saved.credit_type_override||(a.manual_import&&!a.author_listing_verified?'contribution':'author-page');
 host.querySelector('.reviewfields')?.remove();const panel=document.createElement('div');panel.className='reviewfields';
 panel.innerHTML=`<h3>${escape(a.title)}</h3><p>Original byline: ${escape((a.original_authors||[]).join(', ')||'Not recorded')}</p><p>${escape(a.word_count)} words · ${escape(a.source_name)}</p><div class="reviewbody"></div><label>Title<input data-review-title value="${escape(a.title)}"></label><div class="row"><label>Section<select data-review-stream><option value="reporting">Reports & Features</option><option value="opinion">Opinion & Analysis</option><option value="thoughts">Thoughts</option></select></label><label>Credit type<select data-review-credit><option value="author-page">Bylined article</option><option value="contribution">Non-byline contribution</option></select></label><label>Category<input data-review-category value="${escape(a.category)}"></label></div><div class="row"><label>Publication date<input data-review-date type="date" value="${escape(a.date_published?.slice(0,10))}"></label><label>Visibility<select data-review-status><option value="published">Published</option><option value="hidden">Hidden</option></select></label></div><p class="hint">You can move any archived article between sections and change whether it counts as bylined work or a non-byline contribution. The original publisher byline remains saved.</p><button data-review-save>Save classification</button>`;
 panel.querySelector('.reviewbody').textContent=new DOMParser().parseFromString(a.body_html||'','text/html').body.textContent;panel.querySelector('[data-review-stream]').value=a.stream;panel.querySelector('[data-review-credit]').value=inferredCredit;panel.querySelector('[data-review-status]').value=a.status==='hidden'?'hidden':'published';
 panel.querySelector('[data-review-save]').onclick=()=>task(async()=>{const title=panel.querySelector('[data-review-title]').value.trim(),date=panel.querySelector('[data-review-date]').value,status=panel.querySelector('[data-review-status]').value;if(!title||(status==='published'&&!date))throw Error('A title and original publication date are required.');const next={articles:{...overrides.articles,[id]:{...overrides.articles[id],title,stream:panel.querySelector('[data-review-stream]').value,credit_type_override:panel.querySelector('[data-review-credit]').value,category:panel.querySelector('[data-review-category]').value,date_published:date?date+'T00:00:00+06:00':'',status}}};await api.commit([{path:'content/overrides.json',data:next}],'Classify archived story: '+title);overrides=next;notice('Section and credit classification saved. The website will update after deployment.');panel.remove()});host.append(panel)
}
function fillSettings(){$('#setting-url').value=settings.site_url||'';$('#setting-email').value=settings.email||'';$('#setting-linkedin').value=settings.social?.linkedin||'';$('#setting-flickr').value=settings.social?.flickr||'';$('#setting-bio').value=settings.biography||'I am a journalist at The Daily Star, reporting on education, governance, rights, social policy and public accountability.';$('#setting-awards').value=JSON.stringify(settings.recognition||[],null,2)}
$('#connect-form').onsubmit=e=>{e.preventDefault();task(async()=>{api=new GitHub($('#repo').value.trim(),$('#branch').value.trim(),$('#token').value.trim());await load();$('#token').value='';$('#connect').hidden=true;$('#studio').hidden=false;$('#disconnect').hidden=false;$('#connection').textContent=api.repo+' · '+api.branch;$('#workflow-link').href='https://github.com/'+api.repo+'/actions';notice('Connected. All saves are committed to your repository.')})};
$('#disconnect').onclick=()=>{api?.disconnect();api=null;$('#studio').hidden=true;$('#connect').hidden=false;$('#disconnect').hidden=true;$('#token').value='';notice('Disconnected. Your token has been cleared.')};
$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('#story-form').oninput=()=>dirty=true;$('#story-form').onsubmit=e=>{e.preventDefault();task(()=>saveStory('published'))};$('#save-draft').onclick=()=>task(()=>saveStory('draft'));$('#download-draft').onclick=()=>download(draft(),'arafat-story-draft.json');$('#new-story').onclick=()=>{if(dirty&&!confirm('Clear unsaved editor changes? Download the draft first if needed.'))return;$('#story-form').reset();$('#story-id').value='';$('#story-date').value=today();$('#editor-title').textContent='New story';dirty=false};$('#preview-story').onclick=()=>{$('#preview-body').textContent=$('#story-title').value+'\n\n'+$('#story-excerpt').value+'\n\n'+($('#story-format').value==='html'?new DOMParser().parseFromString($('#story-body').value,'text/html').body.textContent:$('#story-body').value);$('#preview-dialog').showModal()};$('#close-preview').onclick=()=>$('#preview-dialog').close();
$('#photo-files').onchange=()=>{const files=[...$('#photo-files').files];if(files.length>12){$('#photo-files').value='';renderPhotoBatch([]);notice('Choose no more than 12 photographs in one batch.',true);return}renderPhotoBatch(files)};
$('#photo-form').onsubmit=e=>{e.preventDefault();task(async()=>{const files=[...$('#photo-files').files];if(!files.length||files.length>12)throw Error('Select between 1 and 12 photographs.');const entries=[],items=[];for(const [index,file] of files.entries()){notice('Preparing photograph '+(index+1)+' of '+files.length+'…');const id=crypto.randomUUID(),path='site/assets/uploads/'+id+'.webp';entries.push({path,bytes:await image(file)});items.push({id,src:path.replace(/^site\//,''),caption:$(`[data-photo-caption="${index}"]`).value.trim(),alt:$(`[data-photo-alt="${index}"]`).value.trim(),location:$(`[data-photo-location="${index}"]`).value.trim(),date:$(`[data-photo-date="${index}"]`).value,status:'published'})}await load();const next={photos:[...items,...photos.photos]};entries.push({path:'content/photos.json',data:next});await api.commit(entries,'Upload '+files.length+' photographs');photos=next;renderPhotos();$('#photo-form').reset();renderPhotoBatch([]);notice(files.length+' photographs saved together. They will appear after deployment.')})};
$('#import-form').onsubmit=e=>{e.preventDefault();task(async()=>{const raw=$('#import-urls').value.split(/\s+/).map(v=>v.trim()).filter(Boolean);if(!raw.length)throw Error('Paste at least one article link.');if(raw.length>100)throw Error('Import no more than 100 links in one batch.');await load();const existing=new Set(imports.imports.map(x=>x.url)),clean=[];for(const value of raw){const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||(u.port&&u.port!=='443'))throw Error('Every entry must be a public HTTPS article URL.');u.hash='';for(const k of [...u.searchParams.keys()])if(k.startsWith('utm_')||['fbclid','gclid'].includes(k))u.searchParams.delete(k);if(u.hostname==='thedailystar.net')u.hostname='www.thedailystar.net';if(!existing.has(u.href)&&!clean.includes(u.href))clean.push(u.href)}if(!clean.length)throw Error('Every pasted link is already queued or archived.');const stream=$('#import-stream').value,credit_type=$('#import-credit').value,category=$('#import-category').value.trim(),contribution=$('#import-contribution').value.trim(),section=stream==='opinion'?'Opinion & Analysis':stream==='thoughts'?'Thoughts':'Reports & Features',requested_at=new Date().toISOString();const additions=clean.map(url=>({id:crypto.randomUUID(),url,stream,credit_type,category,contribution,contribution_confirmed:true,rights_confirmed:true,requested_at,status:'queued'}));const next={imports:[...imports.imports,...additions]};await api.commit([{path:'content/imports.json',data:next}],`Queue ${additions.length} article import${additions.length===1?'':'s'}`);imports=next;renderImports();$('#import-form').reset();notice(additions.length+' article'+(additions.length===1?'':'s')+' queued for '+section+'. Import starts automatically.')})};
$('#reload-data').onclick=()=>task(async()=>{await load();notice('Loaded the latest repository version. Editor text has been retained.')});$('#manager-search').oninput=renderStories;$('#refresh-now').onclick=()=>task(async()=>{await load();await api.dispatch(false);notice('Refresh requested. Follow the run through deployment status above.')});$('#full-refresh').onclick=()=>task(async()=>{await load();await api.dispatch(true);notice('Deep archive scan requested. Remaining articles continue in later runs.')});
$('#settings-form').onsubmit=e=>{e.preventDefault();task(async()=>{const url=new URL($('#setting-url').value);if(url.protocol!=='https:')throw Error('Website URL must use HTTPS.');const awards=JSON.parse($('#setting-awards').value);if(!Array.isArray(awards)||awards.some(a=>!a||typeof a.title!=='string'))throw Error('Awards must be an array of objects with a title.');const linkedin=$('#setting-linkedin').value,flickr=$('#setting-flickr').value;if(linkedin&&new URL(linkedin).protocol!=='https:')throw Error('LinkedIn URL must use HTTPS.');if(flickr&&new URL(flickr).protocol!=='https:')throw Error('Flickr URL must use HTTPS.');const next={...settings,site_url:url.href.replace(/\/$/,''),email:$('#setting-email').value,social:{...settings.social,linkedin,flickr},biography:$('#setting-bio').value,recognition:awards};await api.commit([{path:'content/settings.json',data:next}],'Update portfolio settings');settings=next;notice('Settings saved. The public site will update after deployment.')})};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});$('#story-date').value=today();$('#story-stream option[value="reporting"]').textContent='Reports & Features';
fetch('../data/site.json').then(r=>r.ok?r.json():{}).then(c=>{$('#repo').value=c.publishing?.repository||'arafat-247/arafat-portfolio';$('#branch').value=c.publishing?.branch||'main'}).catch(()=>{$('#repo').value='arafat-247/arafat-portfolio'});
